import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;

public class NthOfScratch {
    public static void main(String[] args) {
        Document doc = Jsoup.parse("<ul><li id=1 class=a></li><li id=2></li><li id=3 class=a></li><li id=4 class=a></li></ul>");
        // 'of *' equivalent to plain nth-child
        System.out.println(doc.select("li:nth-child(2 of *)").first().id()); // 2
        System.out.println(doc.select("li:nth-child(2)").first().id());     // 2
        // nested inside :has
        System.out.println(doc.select("ul:has(> li:nth-child(2 of .a))").size()); // 1
        // combined forward + reverse intersection
        System.out.println(doc.select("li:nth-child(n+2 of .a):nth-last-child(n+2 of .a)").first().id()); // 3
        // :is with of
        System.out.println(doc.select("li:is(:nth-child(1 of .a), :nth-last-child(1 of .a))").size()); // 2
        // signed step, negative offset
        System.out.println(doc.select("li:nth-child(-2n+3 of .a)").size()); // positions 1,3 -> ids 1,4 -> 2
        // constant 0 and negative constant -> no matches
        System.out.println(doc.select("li:nth-child(0 of .a)").size());  // 0
        System.out.println(doc.select("li:nth-child(-3 of .a)").size()); // 0
    }
}
